#!/usr/bin/env python3
"""Public folder indexes, with GitHub landing-page precedence handled explicitly."""
from pathlib import Path
import subprocess,os,sys
from urllib.parse import quote
R=Path(__file__).resolve().parents[1]
files=[Path(p) for p in subprocess.check_output(['git','ls-files','--cached','--others','--exclude-standard'],cwd=R,text=True).splitlines() if (R/p).is_file()]
dirs={p for f in files for p in f.parents if str(p)!='.'}
marker='<!-- generated by tools/write_readmes.py -->'
purpose={'hardware':'Native KiCad source projects, interface authority and pinned library files.','cad':'Parametric enclosure geometry, dimensional authority and print orientation.','exports':'Generated drawings, manufacturing review files, printable parts and validation reports.','preview':'Current rendered evidence of assembly, cable retention and housing geometry.','docs':'Engineering decisions, manufacturing, qualification and progress.','tools':'Reproducible generation, independent checks and release packaging.','research':'Source-backed investigations; unresolved facts are kept explicit.','releases':'Versioned, checksum-listed PCB and enclosure download packages.','.agents':'Canonical engineering lessons and repeatable review procedures.','.github':'CI validation and prerelease publication.'}
changes=[]
if (R/'.github/README.md').exists():raise SystemExit(".github/README.md overrides the root project overview; put CI docs in .github/workflows/README.md")
dirs.discard(Path('.github'))
for d in sorted(dirs):
 p=R/d/'README.md'
 if p.exists() and marker not in p.read_text():continue
 name=d.as_posix();parent=quote(os.path.relpath(R/'README.md',p.parent));desc=purpose.get(name,purpose.get(d.parts[0],'Project assets and review evidence.'))
 children=sorted({f.name for f in files if f.parent==d and f.name!='README.md'})
 subdirs=sorted({f.parts[len(d.parts)] for f in files if len(f.parts)>len(d.parts)+1 and f.parts[:len(d.parts)]==d.parts})
 lines=[marker,f'# {name}','',f'[Project overview]({parent})','',desc,'']
 if d.parts[0] in ['exports','preview','cad','hardware']:lines+=['**A0 engineering prototype.** CAD checks do not establish physical fit, electrical protection or production readiness.','']
 if name=='tools':lines+=['`build_electronics.py` requires KiCad Python (`pcbnew`) and normally overwrites native layouts. Use `--schematic-only` when intentionally preserving routing. Run `finalize_board.py` with KiCad Python after importing the matching route session. `export_review.py`, `check_electronics.py`, `update_evidence.py`, mechanical builds and release validation use the project venv. See the root README for the safe committed-board workflow.','']
 if name=='exports':lines+=['Print only the selected base/lid pair plus the universal clamp; test coupons first. STL/3MF are in print orientation; STEP is in assembly coordinates. Each PCB variant has its own fabrication and assembly population files.','']
 if name=='preview':lines+=['![Two-port cable retention](2port-open.png)','![Four-port assembly](4port-assembled.png)','']
 lines+=['| Item | Kind |','|---|---|']
 lines += [f'| [{s}/]({quote(s)}/README.md) | Folder |' for s in subdirs]
 lines += [f'| [{s}]({quote(s)}) | {Path(s).suffix.lstrip(".") or "text"} |' for s in children]
 text='\n'.join(lines)+'\n'
 if not p.exists() or p.read_text()!=text:
  changes.append(name)
  if '--check' not in sys.argv:p.write_text(text)
if '--check' in sys.argv and changes:raise SystemExit('Missing/stale folder READMEs: '+', '.join(changes))
print(f'{len(dirs)} public folders covered; {len(changes)} README updates')
